class MarginNewPage extends ConsumerStatefulWidget{
 const MarginNewPage({super.key,required this.workspaceId,this.itemId,this.annotationId,this.replyTo});final String workspaceId;final String? itemId,annotationId,replyTo;
 @override ConsumerState<MarginNewPage> createState()=>_MarginNewPageState();
}
class _MarginNewPageState extends ConsumerState<MarginNewPage>{
 final _title=TextEditingController(),_body=TextEditingController(),_quote=TextEditingController();String _kind='note';String? _source,_collection;int? _block;bool _context=false,_label=false,_url=false,_busy=false;Map<String,dynamic>? _preview;
 @override void initState(){super.initState();_source=widget.itemId;if(widget.replyTo!=null){_kind='comment';}_loadAnnotation();}
 Future<void> _loadAnnotation()async{if(widget.annotationId==null||_source==null){return;}try{final repo=await ref.read(bootstrapProvider.future);final a=repo.listAnnotations(_source!).where((a)=>a.id==widget.annotationId).firstOrNull;if(a!=null&&mounted){setState((){_kind='highlight';_title.text='Shared highlight';_quote.text=a.quote;_body.text=a.note??'';_block=a.blockIdx;_preview=null;});}}catch(e){if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
 @override void dispose(){_title.dispose();_body.dispose();_quote.dispose();super.dispose();}
 Map<String,dynamic> get _input=>{'workspace_id':widget.workspaceId,'kind':_kind,'title':_title.text,'body':_body.text,'reply_to':widget.replyTo,'collection_id':_collection,'local_item_id':_source,'block_idx':_block,'quote':_quote.text,'include_context':_context,'share_source_label':_label,'share_source_url':_url};
 Future<void> _pickSource()async{try{final repo=await ref.read(bootstrapProvider.future);final items=repo.listItems(limit:100);if(!mounted){return;}final id=await showDialog<String>(context:context,builder:(ctx)=>SimpleDialog(title:const Text('Choose local source (first 100)'),children:[SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,''),child:const Text('No source attachment')),...items.map((i)=>SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,i.id),child:Text(i.displayTitle)))]));if(id!=null&&mounted){setState((){_source=id.isEmpty?null:id;_block=null;_quote.clear();_preview=null;});}}catch(e){if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
 Future<void> _review()async{setState(()=>_busy=true);Map<String,dynamic>? result;final ok=await marginChange(context,ref,(r){result=r.margins('preview',_input) as Map<String,dynamic>;});if(mounted){setState((){_busy=false;_preview=ok?result:null;});}}
 Future<void> _publish()async{if(_preview==null){return;}if(!await marginConfirm(context,'Place this reviewed copy in the workspace?','This content and future retained revisions may be shared with selected workspace devices. The private original annotation/document remains separate.')){return;}if(!mounted){return;}setState(()=>_busy=true);final ok=await marginChange(context,ref,(r)=>r.margins('publish',{..._input,'review_hash':_preview!['review_hash']}));if(mounted){setState(()=>_busy=false);if(ok){context.pop();}}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Review a selected shared copy')),body:ref.watch(marginWorkspaceProvider(widget.workspaceId)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(w)=>ListView(padding:const EdgeInsets.all(16),children:[
 Text('Workspace: ${w.name} · access: ${w.role}'),const Text('No original document is shared. Quotes, optional surrounding context, heading, title and URL are shared ONLY as shown in the reviewed copy. Private annotations remain private; this creates a separate workspace entry.'),
 DropdownButtonFormField<String>(key:ValueKey(_kind),initialValue:_kind,decoration:const InputDecoration(labelText:'Content kind'),items:['note','highlight','comment','reference','collection'].map((v)=>DropdownMenuItem(value:v,child:Text(v=='collection'?'Research collection / reading list':v))).toList(),onChanged:(v)=>setState((){_kind=v!;_preview=null;})),
 TextField(controller:_title,maxLength:200,decoration:const InputDecoration(labelText:'Shared entry title'),onChanged:(_)=>setState(()=>_preview=null)),TextField(controller:_body,maxLines:4,maxLength:4000,decoration:const InputDecoration(labelText:'Shared note / comment / reference'),onChanged:(_)=>setState(()=>_preview=null)),
 if(widget.replyTo!=null)Text('Discussion reply to entry ${widget.replyTo}'),
 DropdownButtonFormField<String>(initialValue:_collection??'',decoration:const InputDecoration(labelText:'Collection / reading list (optional)'),items:[const DropdownMenuItem(value:'',child:Text('No collection')),...w.entries.where((e)=>!e.deleted&&e.versions.first.kind=='collection').map((e)=>DropdownMenuItem(value:e.id,child:Text(e.versions.first.title)))],onChanged:(v)=>setState((){_collection=v==''?null:v;_preview=null;})),
 OutlinedButton(onPressed:_pickSource,child:Text(_source==null?'Attach explicit local quote (optional)':'Change / remove local source')),
 if(_source!=null)ref.watch(itemProvider(_source!)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(item){if(item==null){return const Text('Local source unavailable.');}return Column(children:[Text('Local source (not automatically shared): ${item.displayTitle}'),DropdownButtonFormField<int>(key:ValueKey('$_source:$_block'),initialValue:_block,decoration:const InputDecoration(labelText:'Source block'),isExpanded:true,items:item.blocks.take(200).map((b)=>DropdownMenuItem(value:b.idx,child:Text('${b.idx}: ${b.text}',maxLines:1,overflow:TextOverflow.ellipsis))).toList(),onChanged:(v)=>setState((){_block=v;_preview=null;})),TextField(controller:_quote,maxLines:3,maxLength:1200,decoration:const InputDecoration(labelText:'Exact quote occurring once in this block'),onChanged:(_)=>setState(()=>_preview=null)),CheckboxListTile(value:_context,title:const Text('Include up to 40 prefix/suffix characters and heading context'),onChanged:(v)=>setState((){_context=v??false;_preview=null;})),CheckboxListTile(value:_label,title:const Text('Include recorded source title'),onChanged:(v)=>setState((){_label=v??false;_preview=null;})),CheckboxListTile(value:_url,title:const Text('Include recorded source URL (may contain sensitive parameters)'),onChanged:(v)=>setState((){_url=v??false;_preview=null;}))]);}),
 FilledButton.tonal(onPressed:_busy||!w.canEdit?null:_review,child:const Text('Build exact sharing preview (does not publish)')),
 if(_preview!=null)...[const ListTile(title:Text('Exact reviewed shared copy')),SelectableText((_preview!['revision'] as Map)['title'] as String),SelectableText((_preview!['revision'] as Map)['body'] as String),if((_preview!['revision'] as Map)['anchor']!=null)...[SelectableText('Quote: ${(_preview!['revision'] as Map)['anchor']['quote']}'),SelectableText('Prefix: ${(_preview!['revision'] as Map)['anchor']['prefix']}\nSuffix: ${(_preview!['revision'] as Map)['anchor']['suffix']}\nHeading: ${(_preview!['revision'] as Map)['anchor']['heading']??'not included'}')],SelectableText('Source label: ${(_preview!['revision'] as Map)['source_label']??'not included'}\nSource URL: ${(_preview!['revision'] as Map)['source_url']??'not included'}'),const Text('Only this copy enters the workspace. Sharing still requires an explicit encrypted transfer.'),FilledButton(onPressed:_busy||!w.canEdit?null:_publish,child:const Text('Place reviewed copy in workspace'))],
 ])));
}
class MarginEditPage extends ConsumerWidget{
 const MarginEditPage({super.key,required this.workspaceId,required this.entryId,required this.revisionId});final String workspaceId,entryId,revisionId;
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Review shared revision')),body:ref.watch(marginWorkspaceProvider(workspaceId)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(w){final entry=w.entries.where((e)=>e.id==entryId).firstOrNull;final revision=entry?.versions.where((r)=>r.id==revisionId).firstOrNull;if(entry==null||revision==null){return const Center(child:Text('This version is no longer a current head. Reload the workspace and review current versions.'));}return _EditForm(key:ValueKey('${w.localRevision}:$revisionId'),workspace:w,entry:entry,revision:revision);}));
}
class _EditForm extends ConsumerStatefulWidget{const _EditForm({super.key,required this.workspace,required this.entry,required this.revision});final MarginWorkspace workspace;final MarginEntry entry;final MarginRevision revision;@override ConsumerState<_EditForm> createState()=>_EditFormState();}
class _EditFormState extends ConsumerState<_EditForm>{late final _title=TextEditingController(text:widget.revision.title),_body=TextEditingController(text:widget.revision.body);late bool _done=widget.revision.done,_deleted=widget.revision.deleted;bool _reviewed=false;
 @override void dispose(){_title.dispose();_body.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[
 Text(widget.entry.conflict?'CONFLICT: saving an explicitly reviewed choice joins all displayed heads, retaining every previous revision.':'Editing creates a new retained revision. Delete marks a shared tombstone; it does not erase past copies.'),
 if(widget.entry.conflict)ExpansionTile(initiallyExpanded:true,title:const Text('All concurrent versions'),children:widget.entry.versions.map((v)=>ListTile(title:Text('${v.title}${v.deleted?' · DELETED':''}'),subtitle:SelectableText(v.body))).toList()),
 TextField(controller:_title,maxLength:200,decoration:const InputDecoration(labelText:'Selected version title')),TextField(controller:_body,maxLines:5,maxLength:4000,decoration:const InputDecoration(labelText:'Selected version text')),SwitchListTile(value:_done,onChanged:(v)=>setState(()=>_done=v),title:const Text('Read / done')),SwitchListTile(value:_deleted,onChanged:(v)=>setState(()=>_deleted=v),title:const Text('Deleted tombstone (history retained)')),const Text('Anchoring and shared source metadata are preserved from the selected version. Create a newly reviewed quoted entry to choose a different passage.'),CheckboxListTile(value:_reviewed,onChanged:(v)=>setState(()=>_reviewed=v??false),title:const Text('I reviewed all current versions and this explicit selection')),
 FilledButton(onPressed:!widget.workspace.canEdit||!_reviewed?null:()async{final ok=await marginChange(context,ref,(r)=>r.margins('edit',{'workspace_id':widget.workspace.id,'entry_id':widget.entry.id,'chosen_revision':widget.revision.id,'expected_heads':widget.entry.versions.map((v)=>v.id).toList(),'title':_title.text,'body':_body.text,'done':_done,'deleted':_deleted}));if(ok&&context.mounted){context.pop();}},child:const Text('Save explicitly reviewed revision')),
 ]);
}
